const EDGE_HIT_MS = 20;   // London/Tokyo POP cache hit
const ORIGIN_MS = 220;    // California origin round-trip

function report(hitRatio) {
  const missRatio = 1 - hitRatio;
  const blended = hitRatio * EDGE_HIT_MS + missRatio * ORIGIN_MS;
  console.log(
    `hit ${(hitRatio*100).toFixed(0)}% -> miss ${(missRatio*100).toFixed(0)}% | ` +
    `blended ${blended.toFixed(1)} ms`
  );
  return { missRatio, blended };
}

const a = report(0.95);
const b = report(0.90);
console.log(`origin traffic x${(b.missRatio / a.missRatio).toFixed(1)} when hit ratio drops 95%->90%`);
